import sys

def solve():
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1]
    T = data[2]

    # Build mapping f: S-letter -> T-letter, check consistency
    f = {}
    for s, t in zip(S, T):
        if s in f:
            if f[s] != t:
                print(-1)
                return
        else:
            f[s] = t

    U_S = set(S)
    U_T = set(T)

    # Already equal
    if all(f[c] == c for c in U_S):
        print(0)
        return

    # Impossibility: all 26 letters in S and all 26 in T (=> f bijective non-identity)
    if len(U_S) == 26 and len(U_T) == 26:
        print(-1)
        return

    # Count edges (letters that need to change)
    edges = sum(1 for c in U_S if f[c] != c)

    # Count cycles in functional graph restricted to U_S with f(c) != c
    visited = {c: 0 for c in 'abcdefghijklmnopqrstuvwxyz'}
    cycles = 0

    for start in U_S:
        if visited[start] != 0:
            continue

        path = []
        cur = start
        while True:
            if cur not in U_S:
                break
            if f[cur] == cur:
                visited[cur] = 2
                break
            if visited[cur] != 0:
                break
            visited[cur] = 1
            path.append(cur)
            cur = f[cur]

        # If we ended on a node currently in our path -> cycle
        if cur in U_S and f[cur] != cur and visited[cur] == 1:
            cycles += 1

        for node in path:
            visited[node] = 2

    print(edges + cycles)

solve()

